namespace local_moderncommerce\external\products;

use context_system;
use core_external\external_api;
use core_external\external_function_parameters;
use core_external\external_single_structure;
use core_external\external_value;
use local_moderncommerce\services\category_service;

/**
 * Save product basics, price, inventory, and primary category.
 */
class save_product extends external_api {
    /**
     * Parameters.
     *
     * @return external_function_parameters
     */
    public static function execute_parameters(): external_function_parameters {
        return new external_function_parameters([
            'id' => new external_value(PARAM_INT, 'Product ID, or 0 for a new product.', VALUE_DEFAULT, 0),
            'producttype' => new external_value(PARAM_ALPHANUMEXT, 'Product type.', VALUE_DEFAULT, 'course'),
            'name' => new external_value(PARAM_TEXT, 'Product name.', VALUE_REQUIRED),
            'slug' => new external_value(
                PARAM_ALPHANUMEXT,
                'Product slug. Deprecated; generated by the server.',
                VALUE_DEFAULT,
                ''
            ),
            'sku' => new external_value(
                PARAM_TEXT,
                'Product SKU. Optional; generated by the server when the SKU form field is hidden or left blank.',
                VALUE_DEFAULT,
                ''
            ),
            'status' => new external_value(PARAM_ALPHANUMEXT, 'Product status.', VALUE_DEFAULT, 'draft'),
            'visible' => new external_value(PARAM_BOOL, 'Whether the product is visible.', VALUE_DEFAULT, true),
            'featured' => new external_value(PARAM_BOOL, 'Whether the product is featured.', VALUE_DEFAULT, false),
            'shortdescription' => new external_value(PARAM_TEXT, 'Short description.', VALUE_DEFAULT, ''),
            'displayorder' => new external_value(PARAM_INT, 'Catalog display order.', VALUE_DEFAULT, 0),
            'categoryid' => new external_value(PARAM_INT, 'Primary category ID, or 0 for none.', VALUE_DEFAULT, 0),
            'courseid' => new external_value(PARAM_INT, 'Linked Moodle course ID for course products.', VALUE_DEFAULT, 0),
            'priceenabled' => new external_value(PARAM_BOOL, 'Whether regular pricing is enabled.', VALUE_DEFAULT, true),
            'regularprice' => new external_value(PARAM_FLOAT, 'Regular price amount.', VALUE_DEFAULT, 0),
            'compareamount' => new external_value(PARAM_FLOAT, 'Compare-at amount.', VALUE_DEFAULT, 0),
            'stockmanaged' => new external_value(PARAM_BOOL, 'Whether stock is managed.', VALUE_DEFAULT, false),
            'stock' => new external_value(PARAM_INT, 'Stock quantity.', VALUE_DEFAULT, 0),
            'reservedstock' => new external_value(PARAM_INT, 'Reserved stock quantity.', VALUE_DEFAULT, 0),
            'allowbackorder' => new external_value(PARAM_BOOL, 'Whether backorders are allowed.', VALUE_DEFAULT, false),
        ]);
    }

    /**
     * Save a product.
     *
     * @param int $id Product ID.
     * @param string $producttype Product type.
     * @param string $name Name.
     * @param string $slug Slug.
     * @param string $sku SKU.
     * @param string $status Status.
     * @param bool $visible Visible flag.
     * @param bool $featured Featured flag.
     * @param string $shortdescription Short description.
     * @param int $displayorder Display order.
     * @param int $categoryid Primary category ID.
     * @param int $courseid Linked course ID.
     * @param bool $priceenabled Price enabled flag.
     * @param float $regularprice Regular price.
     * @param float $compareamount Compare-at amount.
     * @param bool $stockmanaged Stock managed flag.
     * @param int $stock Stock quantity.
     * @param int $reservedstock Reserved stock.
     * @param bool $allowbackorder Backorder flag.
     * @return array
     */
    public static function execute(
        int $id = 0,
        string $producttype = 'course',
        string $name = '',
        string $slug = '',
        string $sku = '',
        string $status = 'draft',
        bool $visible = true,
        bool $featured = false,
        string $shortdescription = '',
        int $displayorder = 0,
        int $categoryid = 0,
        int $courseid = 0,
        bool $priceenabled = true,
        float $regularprice = 0,
        float $compareamount = 0,
        bool $stockmanaged = false,
        int $stock = 0,
        int $reservedstock = 0,
        bool $allowbackorder = false
    ): array {
        global $DB, $USER;

        $params = self::validate_parameters(self::execute_parameters(), [
            'id' => $id,
            'producttype' => $producttype,
            'name' => $name,
            'slug' => $slug,
            'sku' => $sku,
            'status' => $status,
            'visible' => $visible,
            'featured' => $featured,
            'shortdescription' => $shortdescription,
            'displayorder' => $displayorder,
            'categoryid' => $categoryid,
            'courseid' => $courseid,
            'priceenabled' => $priceenabled,
            'regularprice' => $regularprice,
            'compareamount' => $compareamount,
            'stockmanaged' => $stockmanaged,
            'stock' => $stock,
            'reservedstock' => $reservedstock,
            'allowbackorder' => $allowbackorder,
        ]);

        require_login();
        $context = context_system::instance();
        self::validate_context($context);
        require_capability('local/moderncommerce:managecourses', $context);

        $params = self::normalise($params);
        $validation = self::validate_business_rules($params);
        if ($validation !== '') {
            return [
                'success' => false,
                'productid' => 0,
                'message' => $validation,
            ];
        }

        $now = time();
        $transaction = $DB->start_delegated_transaction();
        $existing = null;

        if ($params['id'] > 0) {
            $existing = $DB->get_record('local_moderncommerce_products', ['id' => $params['id']], '*', MUST_EXIST);
            $productid = (int) $existing->id;
            $params['slug'] = self::resolve_product_slug($params, $existing);
            $params['sku'] = self::resolve_product_sku($params, $existing);
            $record = self::build_product_record($params, $now, false);
            $record->id = $productid;
            $record->modifiedby = $USER->id;
            $DB->update_record('local_moderncommerce_products', $record);
            $message = get_string('productupdated', 'local_moderncommerce');
        } else {
            $params['slug'] = self::resolve_product_slug($params);
            $params['sku'] = self::resolve_product_sku($params);
            $record = self::build_product_record($params, $now, true);
            $record->createdby = $USER->id;
            $record->modifiedby = $USER->id;
            $productid = (int) $DB->insert_record('local_moderncommerce_products', $record);
            $message = get_string('productcreated', 'local_moderncommerce');
        }

        self::save_price($productid, $params, $now);
        self::save_inventory($productid, $params, $now);
        category_service::set_primary_category($productid, $params['categoryid']);
        self::save_course_link($productid, $params, $now);

        $transaction->allow_commit();

        \local_moderncommerce\audit\audit_service::record(
            $existing ? 'product_updated' : 'product_created',
            'product',
            $productid,
            [
                'olddata' => $existing,
                'newdata' => $params + ['productid' => $productid],
                'severity' => 'info',
            ]
        );

        return [
            'success' => true,
            'productid' => $productid,
            'message' => $message,
        ];
    }

    /**
     * Return structure.
     *
     * @return external_single_structure
     */
    public static function execute_returns(): external_single_structure {
        return new external_single_structure([
            'success' => new external_value(PARAM_BOOL, 'Whether the product was saved.'),
            'productid' => new external_value(PARAM_INT, 'Product ID.'),
            'message' => new external_value(PARAM_TEXT, 'Result message.'),
        ]);
    }

    /**
     * Normalise parameters for persistence.
     *
     * @param array $params Raw params.
     * @return array Normalised params.
     */
    private static function normalise(array $params): array {
        $params['id'] = max(0, (int) $params['id']);
        $params['producttype'] = self::normalise_choice(
            $params['producttype'],
            ['course', 'bundle', 'program', 'subscription', 'digital'],
            'course'
        );
        $params['name'] = trim((string) $params['name']);
        $params['sku'] = trim((string) $params['sku']);
        // Whether the caller supplied a SKU (the SKU form field was shown and filled). When false,
        // the server generates a unique SKU internally — see resolve_product_sku().
        $params['_skuprovided'] = $params['sku'] !== '';
        $submittedslug = trim((string) $params['slug']);
        $params['_slugprovided'] = $submittedslug !== '';
        $params['slug'] = self::normalise_slug($submittedslug, $params['name']);
        $params['status'] = self::normalise_choice(
            $params['status'],
            ['active', 'draft', 'inactive', 'archived'],
            'draft'
        );
        $params['shortdescription'] = trim(strip_tags((string) $params['shortdescription']));
        $params['displayorder'] = max(0, (int) $params['displayorder']);
        $params['categoryid'] = max(0, (int) $params['categoryid']);
        $params['courseid'] = max(0, (int) $params['courseid']);
        $params['regularprice'] = max(0, (float) $params['regularprice']);
        $params['compareamount'] = max(0, (float) $params['compareamount']);
        $params['stock'] = max(0, (int) $params['stock']);
        $params['reservedstock'] = max(0, (int) $params['reservedstock']);

        if ($params['compareamount'] <= $params['regularprice']) {
            $params['compareamount'] = 0;
        }

        return $params;
    }

    /**
     * Validate business rules that require database checks.
     *
     * @param array $params Normalised params.
     * @return string Empty string when valid, otherwise message.
     */
    private static function validate_business_rules(array $params): string {
        global $DB;

        if ($params['name'] === '') {
            return get_string('productnamerequired', 'local_moderncommerce');
        }

        if ($params['id'] > 0 && !$DB->record_exists('local_moderncommerce_products', ['id' => $params['id']])) {
            return get_string('productnotfound', 'local_moderncommerce');
        }

        // Only reject an admin-supplied SKU that clashes; auto-generated SKUs are made unique below.
        if (
            !empty($params['_skuprovided'])
            && self::field_exists_on_another_product('sku', $params['sku'], $params['id'])
        ) {
            return get_string('duplicatedsku', 'local_moderncommerce');
        }

        if (
            $params['categoryid'] > 0
            && !category_service::category_exists($params['categoryid'])
        ) {
            return get_string('invalidcategory', 'local_moderncommerce');
        }

        if (
            $params['courseid'] > 0
            && !$DB->record_exists_select('course', 'id = :courseid AND id > 1', ['courseid' => $params['courseid']])
        ) {
            return get_string('invalidcourseid', 'local_moderncommerce');
        }

        if (
            $params['producttype'] === 'course'
            && $params['courseid'] > 0
            && self::course_linked_to_another_product($params['courseid'], $params['id'])
        ) {
            return get_string('coursealreadylinkedtoproduct', 'local_moderncommerce');
        }

        if ($params['producttype'] === 'course' && $params['courseid'] <= 0) {
            return get_string('courseidrequired', 'local_moderncommerce');
        }

        return '';
    }

    /**
     * Build a product record.
     *
     * @param array $params Normalised params.
     * @param int $now Current timestamp.
     * @param bool $isnew Whether this is an insert.
     * @return \stdClass
     */
    private static function build_product_record(array $params, int $now, bool $isnew): \stdClass {
        $record = (object) [
            'producttype' => $params['producttype'],
            'name' => $params['name'],
            'slug' => $params['slug'],
            'sku' => $params['sku'],
            'status' => $params['status'],
            'visible' => $params['visible'] ? 1 : 0,
            'featured' => $params['featured'] ? 1 : 0,
            'shortdescription' => $params['shortdescription'],
            'displayorder' => $params['displayorder'],
            'timemodified' => $now,
        ];

        if ($isnew) {
            $record->description = '';
            $record->imageurl = null;
            $record->taxable = 1;
            $record->taxcategory = 'standard';
            $record->enrolduration = 0;
            $record->maxenrollment = null;
            $record->currentenrollment = 0;
            $record->timecreated = $now;
        }

        return $record;
    }

    /**
     * Save regular price state.
     *
     * @param int $productid Product ID.
     * @param array $params Normalised params.
     * @param int $now Current timestamp.
     */
    private static function save_price(int $productid, array $params, int $now): void {
        global $DB;

        $existing = self::get_primary_regular_price($productid);
        $record = (object) [
            'productid' => $productid,
            'pricetype' => 'regular',
            'amount' => $params['regularprice'],
            'compareamount' => $params['compareamount'] > 0 ? $params['compareamount'] : null,
            'minquantity' => 1,
            'maxquantity' => null,
            'startdate' => null,
            'enddate' => null,
            'enabled' => $params['priceenabled'] ? 1 : 0,
            'timemodified' => $now,
        ];

        if ($existing) {
            $record->id = $existing->id;
            $DB->update_record('local_moderncommerce_product_prices', $record);
        } else {
            $record->timecreated = $now;
            $DB->insert_record('local_moderncommerce_product_prices', $record);
        }
    }

    /**
     * Get the canonical regular price row managed by the product form.
     *
     * @param int $productid Product ID.
     * @return \stdClass|false
     */
    private static function get_primary_regular_price(int $productid) {
        global $DB;

        $records = $DB->get_records('local_moderncommerce_product_prices', [
            'productid' => $productid,
            'pricetype' => 'regular',
        ], 'id ASC', '*', 0, 1);

        return $records ? reset($records) : false;
    }

    /**
     * Save inventory state.
     *
     * @param int $productid Product ID.
     * @param array $params Normalised params.
     * @param int $now Current timestamp.
     */
    private static function save_inventory(int $productid, array $params, int $now): void {
        global $DB;

        $existing = $DB->get_record('local_moderncommerce_product_inventory', ['productid' => $productid]);
        $stockmanaged = $params['stockmanaged'];
        $record = (object) [
            'productid' => $productid,
            'stockmanaged' => $stockmanaged ? 1 : 0,
            'stock' => $stockmanaged ? $params['stock'] : null,
            'reservedstock' => $stockmanaged ? min($params['reservedstock'], $params['stock']) : 0,
            'allowbackorder' => $params['allowbackorder'] ? 1 : 0,
            'timemodified' => $now,
        ];

        if ($existing) {
            $record->id = $existing->id;
            $DB->update_record('local_moderncommerce_product_inventory', $record);
        } else {
            $DB->insert_record('local_moderncommerce_product_inventory', $record);
        }
    }

    /**
     * Save course link when explicitly supplied.
     *
     * @param int $productid Product ID.
     * @param array $params Normalised params.
     * @param int $now Current timestamp.
     */
    private static function save_course_link(int $productid, array $params, int $now): void {
        global $DB;

        if ($params['producttype'] !== 'course' || $params['courseid'] <= 0) {
            return;
        }

        $DB->delete_records('local_moderncommerce_product_courses', [
            'productid' => $productid,
            'relationtype' => 'included',
        ]);
        $DB->insert_record('local_moderncommerce_product_courses', (object) [
            'productid' => $productid,
            'courseid' => $params['courseid'],
            'relationtype' => 'included',
            'sortorder' => 10,
            'required' => 1,
            'timecreated' => $now,
        ]);
    }

    /**
     * Resolve the persisted product slug.
     *
     * When the slug field is shown and a value submitted, that value is normalised and made
     * unique. Otherwise new products derive the slug from the product name, while existing
     * products keep their current slug.
     *
     * @param array $params Normalised product params ('slug' already normalised from submitted-or-name).
     * @param \stdClass|null $existing Existing product record, for updates.
     * @return string Unique slug.
     */
    private static function resolve_product_slug(array $params, ?\stdClass $existing = null): string {
        if (
            $existing !== null
            && empty($params['_slugprovided'])
            && trim((string) $existing->slug) !== ''
        ) {
            return (string) $existing->slug;
        }

        // The slug parameter is already normalise_slug() of the submitted slug, or of the name when
        // none was submitted, so it serves as the base for both the editable and generated cases.
        return self::unique_product_slug((string) $params['slug'], (int) $params['id']);
    }

    /**
     * Resolve the persisted product SKU.
     *
     * When the SKU field is shown and a value submitted, that value is used as-is (its uniqueness
     * was already validated). Otherwise the SKU is generated internally: existing products keep
     * their current SKU, and new products get a unique SKU derived from the product name.
     *
     * @param array $params Normalised product params.
     * @param \stdClass|null $existing Existing product record, for updates.
     * @return string Unique SKU.
     */
    private static function resolve_product_sku(array $params, ?\stdClass $existing = null): string {
        if (!empty($params['_skuprovided'])) {
            return (string) $params['sku'];
        }

        if ($existing !== null && trim((string) $existing->sku) !== '') {
            return (string) $existing->sku;
        }

        return self::unique_product_sku(self::skuify((string) $params['name']), (int) $params['id']);
    }

    /**
     * Build a unique product SKU.
     *
     * @param string $base Base SKU.
     * @param int $currentid Current product ID to ignore.
     * @return string Unique SKU.
     */
    private static function unique_product_sku(string $base, int $currentid): string {
        $base = trim($base) !== '' ? trim($base) : 'PRODUCT';
        $candidate = $base;
        $counter = 2;
        while (self::field_exists_on_another_product('sku', $candidate, $currentid)) {
            $candidate = $base . '-' . $counter;
            $counter++;
        }

        return $candidate;
    }

    /**
     * Build a stable, URL/label-safe SKU base from a source string.
     *
     * @param string $value Source value (typically the product name).
     * @return string
     */
    private static function skuify(string $value): string {
        $sku = strtoupper((string) preg_replace('/[^A-Z0-9_-]+/i', '-', trim($value)));
        $sku = trim($sku, '-_');

        return $sku !== '' ? $sku : 'PRODUCT';
    }

    /**
     * Build a unique product slug.
     *
     * @param string $base Base slug.
     * @param int $currentid Current product ID to ignore.
     * @return string Unique slug.
     */
    private static function unique_product_slug(string $base, int $currentid): string {
        global $DB;

        $base = trim($base) !== '' ? trim($base) : 'product';
        $candidate = $base;
        $counter = 2;
        while (self::field_exists_on_another_product('slug', $candidate, $currentid)) {
            $candidate = $base . '-' . $counter;
            $counter++;
        }

        return $candidate;
    }

    /**
     * Check whether a unique product field is used elsewhere.
     *
     * @param string $field Field name.
     * @param string $value Field value.
     * @param int $currentid Current product ID.
     * @return bool
     */
    private static function field_exists_on_another_product(string $field, string $value, int $currentid): bool {
        global $DB;

        $allowedfields = ['sku', 'slug'];
        if (!in_array($field, $allowedfields, true)) {
            return true;
        }

        return $DB->record_exists_select(
            'local_moderncommerce_products',
            "{$field} = :value AND id <> :id",
            ['value' => $value, 'id' => $currentid]
        );
    }

    /**
     * Check if a Moodle course is already mapped to another active course product.
     *
     * @param int $courseid Course ID.
     * @param int $currentid Current product ID.
     * @return bool
     */
    private static function course_linked_to_another_product(int $courseid, int $currentid): bool {
        global $DB;

        return $DB->record_exists_sql(
            "SELECT 1
               FROM {local_moderncommerce_product_courses} pc
               JOIN {local_moderncommerce_products} p ON p.id = pc.productid
              WHERE pc.courseid = :courseid
                AND pc.relationtype = :relationtype
                AND p.producttype = :producttype
                AND p.status <> :archived
                AND p.id <> :currentid",
            [
                'courseid' => $courseid,
                'relationtype' => 'included',
                'producttype' => 'course',
                'archived' => 'archived',
                'currentid' => $currentid,
            ]
        );
    }

    /**
     * Normalise a choice to an allowlist.
     *
     * @param string $value Submitted value.
     * @param array $allowed Allowed values.
     * @param string $fallback Fallback value.
     * @return string
     */
    private static function normalise_choice(string $value, array $allowed, string $fallback): string {
        return in_array($value, $allowed, true) ? $value : $fallback;
    }

    /**
     * Normalise or generate a slug.
     *
     * @param string $slug Submitted slug.
     * @param string $name Product name.
     * @return string
     */
    private static function normalise_slug(string $slug, string $name): string {
        $source = trim($slug) !== '' ? trim($slug) : trim($name);
        $source = strtolower($source);
        $source = preg_replace('/[^a-z0-9_-]+/', '-', $source);
        $source = trim((string) $source, '-_');

        return $source !== '' ? $source : 'product-' . time();
    }
}
